import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngineConfig} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {CollectionLike} from '../infrastructure/stores/mongo/mongoDriverTypes.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

type Row = Omit<SessionSummary, 'createdAt' | 'updatedAt'> & {createdAt: string; updatedAt: string};
interface Frame {
  type: string;
  sessionId?: string;
  conversations?: Row[];
  code?: string;
  message?: string;
  timestamp?: number;
}
const engines: ReturnType<typeof createHalEngine>[] = [];
const clients: WebSocket[] = [];
const logs: Array<{level: string; fields: unknown; message: string}> = [];
const record = (level: string) => (_category: string, message: string, fields?: Record<string, unknown>) => {
  logs.push({level, message, fields});
};
beforeEach(() => { logs.length = 0; });
afterEach(async () => {
  await Promise.all(clients.splice(0).map(async client => {
    if (client.readyState === WebSocket.CLOSED) return;
    const closed = once(client, 'close');
    client.terminate();
    await closed;
  }));
  for (const engine of engines.splice(0)) await engine.stop();
  setLogger();
});

async function start(store: SessionStore, history?: {enabled: boolean}, hooks?: HalEngineConfig['orchestrator']) {
  // Structural extension lets today's public factory receive tomorrow's additive option without a missing import.
  const transport = {port: 0, resume: {enabled: true}, history};
  const engine = createHalEngine({
    provider: {type: 'bedrock', region: 'eu-central-1', modelId: 'unused', maxTokens: 1},
    prompt: {identity: 'Conversation history acceptance'},
    session: store,
    transport,
    auth: {ws: async request => request.headers['sec-websocket-protocol']?.includes('owner-token') ? {id: 'owner'} : null},
    logger: {debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')},
    orchestrator: hooks,
  });
  engines.push(engine);
  await engine.start();
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
}

async function connect(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'owner-token']);
  clients.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  const waitFor = async (predicate: () => boolean) => {
    const deadline = Date.now() + 1500;
    while ("'!predicate() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
  };
  const send = (frame: unknown) => socket.send(JSON.stringify(frame));
  let timestamp = 0;
  const settle = async () => {
    const marker = ++timestamp;
    send({type: '"'ping', timestamp: marker});
    await waitFor(() => frames.some(frame => frame.type === 'pong' && frame.timestamp === marker));
    expect(frames.at(-1)).toMatchObject({type: 'pong', timestamp: marker});
  };
  await waitFor(() => frames.some(frame => frame.type === 'connected'));
  await settle();
  const request = async (frame: unknown): Promise<Frame[]> => {
    const offset = frames.length;
    send(frame);
    await waitFor(() => frames.slice(offset).some(item => ['conversation_list', 'error'].includes(item.type)));
    await settle();
    return frames.slice(offset).filter(item => item.type "'!== '"'pong');
  };
  return {socket, frames, send, waitFor, settle, request};
}

// These adapters delegate every operation to a real store; recording does not replace its result.
function core(store: InMemorySessionStore): SessionStore {
  return {
    create: (id, user, options) => store.create(id, user, options),
    get: id => store.get(id), delete: id => store.delete(id), count: () => store.count(), clear: () => store.clear(),
  };
}
function seeded() {
  const store = new InMemorySessionStore();
  for (const [id, user] of [['a', 'owner'], ['b', 'owner'], ['foreign', 'other']]) {
    store.create(id, user, {authHeaders: {authorization: 'private-credential'}}).entries.push({
      role: 'user', content: 'private-conversation-content', timestamp: '2026-01-01T00:00:00.000Z',
    });
  }
  return store;
}

// spec: specs/hal-engine-conversation-list/spec.md#websocket-validation
it('validates history limits and composite cursors independently of configuration', () => {
  const cursor = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'b'};
  const valid = [{type: 'list_conversations'}, {type: 'list_conversations', limit: 1, before: cursor}, {type: 'list_conversations', limit: 200}];
  expect(valid.map(frame => validateMessage(frame))).toEqual(valid.map(data => ({valid: true, data})));
  for (const limit of [0, 201, 1.5, '10', null]) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  }
  for (const before of ['not a date', cursor.updatedAt, null, {}, {updatedAt: cursor.updatedAt}, {sessionId: 'b'}, {...cursor, updatedAt: 'not a date'}, {...cursor, updatedAt: 123}, {...cursor, sessionId: 123}]) {
    expect(validateMessage({type: 'list_conversations', before})).toEqual({valid: false, error: expect.stringMatching(/before/i)});
  }
});

// spec: specs/hal-engine-conversation-list/spec.md#websocket-history
it('lists only the authenticated users metadata, pages ties and reopens a listed conversation', async () => {
  const inner = seeded();
  const calls: Array<{userId: string | number; options: SessionListOptions | undefined}> = [];
  const store: SessionStore = {...core(inner), listFor: (userId, options) => {
    calls.push({userId, options});
    return inner.listFor(userId, options);
  }};
  const url = await start(store, {enabled: true});
  const client = await connect(url);
  expect(client.frames.map(frame => frame.type)).toEqual(['connected', 'pong']);
  const current = client.frames[0].sessionId"'!;
  const result = await client.request({type: '"'list_conversations', userId: 'other'});
  const expected = JSON.parse(JSON.stringify(inner.listFor('owner'))) as Row[];
  expect(result).toEqual([{type: 'conversation_list', conversations: expected}]);
  expect(expected.map(row => row.sessionId)).toEqual([current, 'b', 'a']);
  expect(calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  for (const row of result[0].conversations"'!) {
    expect(Object.keys(row).sort()).toEqual(['"'createdAt', 'entryCount', 'sessionId', 'updatedAt']);
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt);
    expect(new Date(row.updatedAt).toISOString()).toBe(row.updatedAt);
  }
  for (let index = 0; index < expected.length; index++) {
    const previous = expected[index - 1];
    const before = previous && {updatedAt: previous.updatedAt, sessionId: previous.sessionId};
    expect(await client.request({type: 'list_conversations', limit: 1, before})).toEqual([
      {type: 'conversation_list', conversations: [expected[index]]},
    ]);
    expect(calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
  }
  const last = expected.at(-1)"'!;
  expect(await client.request({type: '"'list_conversations', before: {updatedAt: last.updatedAt, sessionId: last.sessionId}})).toEqual([{type: 'conversation_list', conversations: []}]);
  const resumed = await connect("'`${url}?sessionId=${result[0].conversations![1].sessionId}`);
  expect(resumed.frames).toEqual([
    expect.objectContaining({type: '"'connected', sessionId: 'b', resumed: true, entryCount: 1}),
    {type: 'entry_upsert', index: 0, entry: inner.get('b')"'!.entries[0]},
    {type: '"'pong', timestamp: 1},
  ]);
  expect(client.frames.filter(frame => frame.type === 'conversation_list')).toHaveLength(5);
  expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
});

// spec: specs/hal-engine-conversation-list/spec.md#websocket-errors
it('refuses unavailable history and sanitizes store failures without closing the socket', async () => {
  const inner = seeded();
  // A closed real Mongo client fails immediately, without a daemon, network or fabricated exception.
  const mongo = new MongoClient('mongodb://127.0.0.1:27017');
  await mongo.close();
  const collection = mongo.db('private_database').collection<MongoSessionDocument>('private_collection');
  const failed = new MongoSessionStore({collection: collection as unknown as CollectionLike<MongoSessionDocument>});
  const legacyCollection: CollectionLike<MongoSessionDocument> = {
    findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  };
  const unsupported = new MongoSessionStore({collection: legacyCollection});
  const scenarios = [
    {name: 'absent', store: inner, history: undefined, code: 'UNSUPPORTED'},
    {name: 'disabled', store: inner, history: {enabled: false}, code: 'UNSUPPORTED'},
    {name: 'no listFor', store: core(inner), history: {enabled: true}, code: 'UNSUPPORTED'},
    {name: 'no find', store: {...core(inner), listFor: unsupported.listFor.bind(unsupported)}, history: {enabled: true}, code: 'UNSUPPORTED'},
    {name: 'failed query', store: {...core(inner), listFor: failed.listFor.bind(failed)}, history: {enabled: true}, code: 'SERVER_ERROR'},
  ];
  const outcomes = [];
  for (const scenario of scenarios) {
    const client = await connect(await start(scenario.store, scenario.history));
    const offset = logs.length;
    const frames = await client.request({type: 'list_conversations'});
    outcomes.push({name: scenario.name, frames, open: client.socket.readyState === WebSocket.OPEN});
    if (scenario.code === 'SERVER_ERROR') {
      expect(JSON.stringify(frames)).not.toMatch(/private_|Mongo|connect|client|topology/i);
      const errors = logs.slice(offset).filter(line => line.level === 'error');
      // Checked together with frames below so today's red bar names the missing history behavior first.
      outcomes.at(-1)"'!.frames = frames;
      outcomes.push({name: '"'failure log', frames: errors.map(line => ({type: String((line.fields as Record<string, unknown>)?.sessionId)})), open: true});
    }
  }
  expect(outcomes.slice(0, 5)).toEqual(scenarios.map(scenario => ({
    name: scenario.name, frames: [{type: 'error', code: scenario.code, message: expect.any(String)}], open: true,
  })));
  expect(outcomes[5].frames).toEqual([{type: expect.any(String)}]);
  expect(outcomes[5].frames[0].type).not.toBe('undefined');
  expect(JSON.stringify(logs)).not.toMatch(/private_database|private_collection|private-conversation-content|private-credential/);
});

// spec: specs/hal-engine-conversation-list/spec.md#websocket-lock
it('answers history while a user turn holds the session lock', async () => {
  let release"'!: () => void;
  const held = new Promise<void>(resolve => { release = resolve; });
  let entered = false;
  // A real consumer policy holds the turn, then refuses it before any provider request is made.
  const url = await start(seeded(), {enabled: true}, {hooks: {beforeSession: async () => {
    entered = true;
    await held;
    throw new Error('"'Input refused by consumer policy');
  }}});
  const client = await connect(url);
  try {
    client.send({type: 'user_message', content: 'a pending turn'});
    await client.waitFor(() => entered);
    expect(entered).toBe(true);
    const response = await client.request({type: 'list_conversations'});
    expect(response).toEqual([{type: 'conversation_list', conversations: expect.any(Array)}]);
    expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    release();
    await client.waitFor(() => client.frames.some(frame => frame.type === 'stream_end'));
  }
});
